{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "The closest analogue, [18F]6FPWAY, showed rapid brain uptake in monkeys with a maximal uptake of 4.33% of the injected dose, directly demonstrating meaningful CNS access for the WAY-100635 scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "[carbonyl-11C]WAY-100635, the direct parent scaffold of the query, showed good maximal brain uptake of 5.0% in cynomolgus monkeys by PET.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "[3H]WAY-100635 penetrated the BBB in mice, with brain radioactivity reaching 1.5-1.8% of injected dose and a distribution matching 5-HT1A receptor density.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "The fluoromethyl analogue 18F-mefway entered human brain rapidly with a peak SUV of 1.7, confirming CNS penetration of this scaffold in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "[18F]FCWAY, another close analogue, is BBB-permeable and has been used successfully as a 5-HT1A PET tracer in rodents and humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "WAY-100635 is a P-gp substrate, but its brain uptake is only two- to threefold increased by cyclosporin A modulation, indicating meaningful baseline brain penetration despite efflux liability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple close structural analogues of the query, including WAY-100635, mefway, FCWAY, and 6FPWAY, consistently show rapid and meaningful brain uptake across rodents, monkeys, and humans despite P-gp efflux liability; therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental measurement exists for the exact norbornane-substituted query; extrapolation relies on close WAY-100635 analogues.",
    "Quantitative unbound brain-to-plasma ratio for the query is not available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

